// Extrai a mensagem do payload da Evolution e decide se o agente deve responder.
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};

const event = String(body.event || '').toLowerCase().replace(/_/g, '.');
if (event !== 'messages.upsert') return [];

const data = Array.isArray(body.data) ? body.data[0] : (body.data || {});
const key = data.key || {};

// Contas novas chegam como @lid; a Evolution informa o número real em campos alternativos.
let jid = String(key.remoteJid || '');
if (jid.endsWith('@lid')) jid = String(key.remoteJidAlt || key.senderPn || data.senderPn || jid);
if (!jid.endsWith('@s.whatsapp.net')) return []; // grupos, status, canais

const phone = jid.split('@')[0].split(':')[0];
const type = String(data.messageType || '');
const IGNORED = ['reactionMessage', 'protocolMessage', 'senderKeyDistributionMessage', 'pollUpdateMessage', 'stickerMessage', 'editedMessage'];
if (IGNORED.includes(type)) return [];

const m = data.message || {};
let text = String(
  m.conversation || m.extendedTextMessage?.text || m.imageMessage?.caption || m.videoMessage?.caption || ''
).trim();

const MARK = String.fromCharCode(8203); // marca invisível das mensagens automáticas
const store = $getWorkflowStaticData('global');
store.paused = store.paused || {};
const now = Date.now();
for (const k of Object.keys(store.paused)) {
  if (store.paused[k] < now) delete store.paused[k];
}

if (key.fromMe) {
  if (text.includes(MARK)) return [];                 // enviada pelo agente ou pelo sistema
  if (text.toLowerCase() === '#agente') {             // alguém do salão devolve a conversa ao agente
    delete store.paused[phone];
    return [];
  }
  // Alguém do salão respondeu manualmente: o agente se cala nesta conversa.
  store.paused[phone] = now + Number(cfg.pauseHours || 12) * 60 * 60 * 1000;
  return [];
}

if (store.paused[phone]) return [];

if (!text) {
  const labels = { audioMessage: 'um áudio', imageMessage: 'uma imagem', videoMessage: 'um vídeo', documentMessage: 'um documento', locationMessage: 'uma localização', contactMessage: 'um contato' };
  text = '[O cliente enviou ' + (labels[type] || 'uma mensagem que não é texto') + '. Você não consegue abrir; peça que escreva em texto.]';
}

return [{ json: { phone, pushName: String(data.pushName || ''), text, messageId: String(key.id || '') } }];
